args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Empress_Xiaojingxian dbo:spouse ?spouse .
  {
    ?spouse dbp:father ?father .
  } UNION {
    ?spouse dbo:parent ?father .
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER (lang(?fatherLabel) = 'en') }
}

